-- Packing categories (ADR 0018): every thing on a list and in a bundle has a
-- category, so a list can be shown by category instead of by bundle.

CREATE TYPE "PackingCategory" AS ENUM ('CLOTHING', 'TOILETRIES', 'HEALTH', 'ELECTRONICS', 'DOCUMENTS', 'KIDS', 'FOOD', 'OUTDOOR', 'HOME', 'LEISURE', 'OTHER');

ALTER TABLE "PackingBundleItem" ADD COLUMN "category" "PackingCategory" NOT NULL DEFAULT 'OTHER';

ALTER TABLE "PackingItem" ADD COLUMN "category" "PackingCategory" NOT NULL DEFAULT 'OTHER';

-- ─── First categories, guessed from the names ───────────────────

-- Generated from CATEGORY_KEYWORDS in apps/web/lib/application/packing/
-- categories.ts as it was when this migration was written; the first
-- category whose keywords match wins. Null when nothing matches. Æ, Ø and Å
-- are lowered by hand, since lower() leaves them alone under the C locale.
CREATE FUNCTION "_guess_packing_category"(name TEXT) RETURNS "PackingCategory"
