  END)::"PackingCategory"
  FROM (
    SELECT lower(translate(regexp_replace(btrim(name), '\s+', ' ', 'g'), 'ÆØÅÄÖÜÉÈ', 'æøåäöüéè')) AS normalized
  ) AS input
$$;

-- Bundle items: by their own name, else by the bundle's ("Toalettsaker").
UPDATE "PackingBundleItem" AS item
SET "category" = COALESCE(
  "_guess_packing_category"(item."name"),
  "_guess_packing_category"(bundle."name"),
  'OTHER'
)
FROM "PackingBundle" AS bundle
WHERE bundle."id" = item."bundleId";

-- Things copied from a bundle item get its category, so a list and its
-- bundle agree.
UPDATE "PackingItem" AS item
SET "category" = bundle_item."category"
FROM "PackingBundleItem" AS bundle_item
WHERE item."bundleItemId" = bundle_item."id";

-- The rest: by name, else by the bundle they came from, else by the sub-list
-- they are in.
UPDATE "PackingItem" AS item
SET "category" = COALESCE(
  "_guess_packing_category"(item."name"),
  (SELECT "_guess_packing_category"(bundle."name")
     FROM "PackingBundle" AS bundle WHERE bundle."id" = item."bundleId"),
  (SELECT "_guess_packing_category"(list_group."name")
     FROM "PackingListGroup" AS list_group WHERE list_group."id" = item."groupId"),
  'OTHER'
)
WHERE item."bundleItemId" IS NULL;

DROP FUNCTION "_guess_packing_category"(TEXT);
